using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static partial class StackHouse3DSigns{
public static Mesh BuildHospitalOpenRoadside(Material material,bool detailed){atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"))));var g=new G();surfaceType=0;var dark=ColorUV(new Color(.035f,.045f,.055f));var blue=ColorUV(new Color(.015f,.53f,1));var white=ColorUV(new Color(.97f,.97f,.97f));var red=ColorUV(new Color(.9f,.015f,.04f));var words=JsonUtility.FromJson<LetterContours>(File.ReadAllText("Assets/Scenes/Oasis/CityHospital/Hospital Roadside Contours.json")).words;
Action<List<Vector2[]>,Vector2,float,float> extrude=(loops,color,front,back)=>{FillContours(g,loops,front,color,0);if(detailed)foreach(var loop in loops)for(int i=0;i<loop.Length;i++){var a=loop[i];var b=loop[(i+1)%loop.Length];g.Quad(new Vector3(a.x,a.y,front),new Vector3(a.x,a.y,back),new Vector3(b.x,b.y,back),new Vector3(b.x,b.y,front),dark,dark,dark,dark);}};
for(int side=0;side<2;side++){int first=g.p.Count;foreach(var word in words){bool city=word.text=="CITY";float cx=0,cy=city?1.1f:-1.0f,w=city?5.5f:10.2f,h=city?1.6f:1.85f;var pts=word.loops.SelectMany(l=>l.points).ToArray();float x0=pts.Min(p=>p.x),x1=pts.Max(p=>p.x),y0=pts.Min(p=>p.y),y1=pts.Max(p=>p.y);var loops=word.loops.Select(l=>l.points.Select(p=>new Vector2(cx-((p.x-x0)/(x1-x0)-.5f)*w,cy+(.5f-(p.y-y0)/(y1-y0))*h)).ToArray()).ToList();float grid=detailed?.035f:.14f;loops=loops.Select(l=>l.Select(v=>new Vector2(Mathf.Round(v.x/grid)*grid,Mathf.Round(v.y/grid)*grid)).ToArray()).ToList();extrude(loops,city?blue:white,.40f,-.10f);}
var cross=new[]{new Vector2(-.36f,1),new Vector2(.36f,1),new Vector2(.36f,.36f),new Vector2(1,.36f),new Vector2(1,-.36f),new Vector2(.36f,-.36f),new Vector2(.36f,-1),new Vector2(-.36f,-1),new Vector2(-.36f,-.36f),new Vector2(-1,-.36f),new Vector2(-1,.36f),new Vector2(-.36f,.36f)};var outer=new List<Vector2[]>{cross.Select(p=>p*1.1f+Vector2.up*3.35f).ToArray()};extrude(outer,red,.44f,-.16f);var inner=new List<Vector2[]>{cross.Select(p=>p*.81f+Vector2.up*3.35f).ToArray()};extrude(inner,white,.52f,.44f);if(side==1)for(int i=first;i<g.p.Count;i++)g.p[i]=Quaternion.Euler(0,180,0)*g.p[i];}
// Narrow rear rails connect the freestanding lettering without a panel.
g.Box(new Vector3(0,-1,0),new Vector3(9.8f,.14f,.16f),dark);g.Box(new Vector3(0,1.1f,0),new Vector3(5.2f,.14f,.16f),dark);g.Box(new Vector3(0,1.1f,0),new Vector3(.14f,4.9f,.16f),dark);foreach(float x in new[]{-1.2f,1.2f})g.Box(new Vector3(x,-1.48f,0),new Vector3(.13f,.96f,.18f),dark);var mesh=new Mesh{name=detailed?"Hospital massive freestanding raised lettering near":"Hospital massive freestanding lettering distant"};WriteG(mesh,g);UnityEngine.Object.DestroyImmediate(atlas);return mesh;}
}
